// The scale cities of M3-20 (PRD, "Scale checkpoints"): each of 50,000,
// 200,000 and 500,000 residents, generated by the sim's
// `generateScaleCity`, loaded from its bytes as a city file opens, and run
// for two game days with every system timed. Run with `pnpm bench`.
//
// It lives in the client because it reads a clock to time each system, as
// the host does through the sim's timer hook (CLAUDE.md rule 3 keeps the
// clock out of packages/sim, its tests included).
//
// For each city it records the pops, the buildings, the snapshot's size,
// how long the load takes (the bytes read and the derived data built), the
// mean and worst time of every system over the two days, and the worst
// tick. The table goes to the log, to the GitHub job summary when there is
// one, and to bench-results/scale-cities.md.
//
// The mean step is held to the tick (`cities.step` in the sim's
// budgets.json). A system's worst tick is one sample of 200, so it is
// shown against that system's share of the tick from its own figure and
// not held: the system's own bench holds it, on many runs. One over its
// share gets an issue (M3-20).

import { appendFileSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { performance } from "node:perf_hooks";
import { expect, test } from "vitest";
import {
  ARRIVALS_SYSTEM,
  DEMAND_SYSTEM,
  GROWER_SYSTEM,
  JOBS_SYSTEM,
  LAND_VALUE_SYSTEM,
  SATISFACTION_SYSTEM,
  SCALE_CITY_RESIDENTS,
  TIME_BALANCE,
  TURNOVER_SYSTEM,
  VACANCY_SYSTEM,
  budgetFigure,
  buildScaleCity,
  buildingCount,
  deserialize,
  generateScaleCity,
  prepareDerived,
  serialize,
  step,
  type GeneratedScaleCity,
  type ScaleCity,
  type ScaleCityResidents,
  type SystemTimer,
} from "@city-council/sim";
import { holdDemandBars } from "../src/protocol/held-demand";
import { hold } from "./budget";

/** Two game days. */
const TICKS = 2 * TIME_BALANCE.ticksPerDay;

/** Each system's share of the 20 ms tick: the budget of its own bench's figure in budgets.json. */
const SHARES: Readonly<Record<string, string>> = {
  [DEMAND_SYSTEM]: "demand.tick",
  [ARRIVALS_SYSTEM]: "arrivals.tick",
  [JOBS_SYSTEM]: "jobs.tick",
  [SATISFACTION_SYSTEM]: "satisfaction.tick",
  [TURNOVER_SYSTEM]: "turnover.tick",
  [VACANCY_SYSTEM]: "vacancy.tick",
  [LAND_VALUE_SYSTEM]: "landvalue.tick",
  [GROWER_SYSTEM]: "grower.share",
};

interface SystemTimes {
  total: number;
  worst: number;
  /** The tick its worst time was on. */
  worstTick: number;
}

interface CityRun {
  residents: ScaleCityResidents;
  population: number;
  pops: number;
  buildings: number;
  snapshotBytes: number;
  generateMs: number;
  loadMs: number;
  stepMeanMs: number;
  worstStepMs: number;
  worstStepTick: number;
  systems: Map<string, SystemTimes>;
  endPopulation: number;
}

const round = (x: number, places = 2): number => Math.round(x * 10 ** places) / 10 ** places;
const mb = (bytes: number): number => round(bytes / 1024 / 1024, 1);

/** Runs a full collection, so the garbage of what came before is not collected inside a timed tick. The bench runs with --expose-gc. */
const collect = (): void => (globalThis as { gc?: () => void }).gc?.();

/** A generated city as a city file holds it, with what the generator reported. */
interface Generated {
  residents: ScaleCityResidents;
  bytes: Uint8Array;
  totals: GeneratedScaleCity["totals"];
  generateMs: number;
}

/** Generates the city of `residents` on a copy of the scale city, `shape` and the snapshot `base`. */
function generate(residents: ScaleCityResidents, shape: Omit<ScaleCity, "state">, base: Uint8Array): Generated {
  const t0 = performance.now();
  const city = generateScaleCity(residents, { ...shape, state: deserialize(base).state });
  const generateMs = performance.now() - t0;
  return { residents, bytes: serialize(city.state), totals: city.totals, generateMs };
}

/**
 * A game day on a copy of `city`, untimed, with every bar held at 100, so
 * the ticks timed after it are not the ones that compile the systems. The
 * bars are held so the grower adds buildings and pops move in and take
 * jobs on most of its ticks: a day at the city's own bars runs those paths
 * a few times or not at all, and the timed run then met them on its first
 * call. On the 500,000 city that put the grower's worst tick over its share
 * on the tick it first added a workplace, its pass over the workplaces 3.8
 * ms on the first call and 0.7 ms from the third (issue #354). That pass
 * is gone since #366, which found the engine threw its compiled code away
 * when the warm-up's city was collected; the day still compiles the rest.
 * Returns the buildings the day added.
 */
function warmUp(city: Generated): number {
  const state = deserialize(city.bytes).state;
  prepareDerived(state);
  const before = buildingCount(state.buildings);
  const letGo = holdDemandBars(100);
  try {
    for (let k = 0; k < TIME_BALANCE.ticksPerDay; k++) step(state);
  } finally {
    letGo();
  }
  return buildingCount(state.buildings) - before;
}

/** Loads `city` from its bytes as a city file opens and runs it for `ticks`, every system timed. */
function runCity(city: Generated, ticks = TICKS): CityRun {
  const { residents, bytes, totals, generateMs } = city;
  collect();
  // As a city file opens: the bytes read, then the derived data the host builds.
  const t0 = performance.now();
  const state = deserialize(bytes).state;
  prepareDerived(state);
  const loadMs = performance.now() - t0;
  collect();

  const systems = new Map<string, SystemTimes>();
  let started = 0;
  let stepMs = 0;
  const timer: SystemTimer = {
    start: () => void (started = performance.now()),
    end: (name) => {
      const ms = performance.now() - started;
      stepMs += ms;
      const s = systems.get(name) ?? { total: 0, worst: 0, worstTick: 0 };
      s.total += ms;
      if (ms > s.worst) {
        s.worst = ms;
        s.worstTick = state.tick;
      }
      systems.set(name, s);
    },
  };
  let total = 0;
  let worst = 0;
  let worstTick = 0;
  for (let k = 0; k < ticks; k++) {
    stepMs = 0;
    const tick = state.tick;
    step(state, timer);
    total += stepMs;
    if (stepMs > worst) {
      worst = stepMs;
      worstTick = tick;
    }
  }
  return {
    residents,
    population: totals.population,
    pops: totals.pops,
    buildings: totals.buildings,
    snapshotBytes: bytes.byteLength,
    generateMs,
    loadMs,
    stepMeanMs: total / ticks,
    worstStepMs: worst,
    worstStepTick: worstTick,
    systems,
    endPopulation: state.stats.totals["population"] ?? 0,
  };
}

function table(runs: readonly CityRun[]): string {
  const names = [...new Set(runs.flatMap((r) => [...r.systems.keys()]))];
  const head = ["", ...runs.map((r) => `${r.residents.toLocaleString("en")}`)];
  const row = (label: string, cells: string[]) => `| ${label} | ${cells.join(" | ")} |`;
  const lines = [
    `### Scale cities: two game days each (${TICKS} ticks)`,
    "",
    row(head[0] ?? "", head.slice(1)),
    `|---|${runs.map(() => "---:").join("|")}|`,
    row("Population", runs.map((r) => r.population.toLocaleString("en"))),
    row("Population after two days", runs.map((r) => r.endPopulation.toLocaleString("en"))),
    row("Pops", runs.map((r) => r.pops.toLocaleString("en"))),
    row("Buildings", runs.map((r) => r.buildings.toLocaleString("en"))),
    row("Snapshot", runs.map((r) => `${mb(r.snapshotBytes)} MB`)),
    row("Generate, ms", runs.map((r) => `${Math.round(r.generateMs)}`)),
    row("Load (read and derive), ms", runs.map((r) => `${Math.round(r.loadMs)}`)),
    row("Step, mean ms", runs.map((r) => `${round(r.stepMeanMs)}`)),
    row("Worst tick, ms", runs.map((r) => `${round(r.worstStepMs)} (tick ${r.worstStepTick})`)),
    "",
    "Each system's mean / worst ms over the two days, and the tick of its worst, against its share of the 20 ms tick where it has one. **Over** marks a worst past its share.",
    "",
    row("System", [...runs.map((r) => `${r.residents.toLocaleString("en")}`), "Share, ms"]),
    `|---|${runs.map(() => "---:").join("|")}|---:|`,
  ];
  for (const name of names) {
    const share = SHARES[name] ? budgetFigure(SHARES[name]).budget : null;
    const cells = runs.map((r) => {
      const s = r.systems.get(name);
      if (!s) return "";
      const over = share !== null && s.worst > share ? " **over**" : "";
      return `${round(s.total / TICKS, 3)} / ${round(s.worst)} (tick ${s.worstTick})${over}`;
    });
    lines.push(row(name, [...cells, share === null ? "" : `${share}`]));
  }
  return `${lines.join("\n")}\n`;
}

/**
 * The scale city's shape and snapshot, without its state. Built by stepping,
 * that state is still walking a change of roads whose queue holds over a
 * million objects. Held for the whole test, it was half the heap, and a
 * collection that landed in a timed tick of the 500,000 city took 260 to
 * 330 ms where the worker's own heap takes 5 to 15 (issue #355).
 */
function scaleCityBase(): { shape: Omit<ScaleCity, "state">; base: Uint8Array } {
  const { state, ...shape } = buildScaleCity();
  return { shape, base: serialize(state) };
}

test("the scale cities, two game days each", () => {
  const { shape, base } = scaleCityBase();
  const cities = SCALE_CITY_RESIDENTS.map((residents) => generate(residents, shape, base));
  // A day on a copy of the first, untimed, so no city's ticks are the ones that compile the systems.
  const warmed = warmUp(cities[0] as Generated);
  console.log(`The warm-up day added ${warmed} buildings.`);
  expect(warmed, "the warm-up day added no buildings, so it compiled none of the grower's building paths").toBeGreaterThan(0);
  const runs = cities.map((city) => runCity(city));
  for (const run of runs) {
    // `cities.step` in the sim's budgets.json: the mean step inside the tick.
    hold("cities.step", `a step on the scale city of ${run.residents.toLocaleString("en")}`, { mean: run.stepMeanMs, max: run.worstStepMs });
    expect(run.population).toBeGreaterThan(0);
  }
  const text = table(runs);
  console.log(text);
  mkdirSync("bench-results", { recursive: true });
  writeFileSync(join("bench-results", "scale-cities.md"), text);
  const summary = process.env["GITHUB_STEP_SUMMARY"];
  if (summary) appendFileSync(summary, `${text}\n`);
}, 600_000);
